export function evaluate({ inputs, time }) {
  const v0 = inputs.launchSpeed;
  const g = 9.8;
  const tTop = v0 / g;
  const clampedT = Math.min(time, 2 * tTop);
  const hMax = (v0 * v0) / (2 * g);
  const v = v0 - g * clampedT;
  const h = v0 * clampedT - 0.5 * g * clampedT * clampedT;

  let motionStateStr = 'Moving up';
  if (Math.abs(v) < 0.05 || Math.abs(clampedT - tTop) < 0.01) {
    motionStateStr = 'Still for an instant';
  } else if (v < 0) {
    motionStateStr = 'Moving down';
  }
  const gravityStateStr = 'Gravity pulls down';

  const objects = [];

  const panel = sdk.panel({
    x: 20,
    y: 20,
    w: 600,
    h: 380,
    title: 'Vertical Toss Scene',
    state: motionStateStr,
    id: 'lane.toss'
  });
  objects.push(...panel);

  const axisX = 140;
  const axisY = 60;
  const axisLen = 300;
  const maxScaleH = 1.6;
  const axis = sdk.axis('axis.height', {
    x: axisX,
    y: axisY,
    length: axisLen,
    orientation: 'y',
    min: 0,
    max: maxScaleH,
    ticks: [0, 0.4, 0.8, 1.2, 1.6],
    label: 'Height',
    unit: 'm'
  });
  objects.push(axis);

  const ballX = 320;
  const ballY = axisY + axisLen - (h / maxScaleH) * axisLen;
  const ball = sdk.circle('ball.toss', ballX, ballY, 28);
  objects.push(ball);

  if (Math.abs(v) >= 0.05) {
    const vecV = sdk.vector('vec.v', { x: ballX, y: ballY }, {
      value: v,
      direction: 'up',
      scale: 15,
      label: 'v'
    });
    objects.push(...vecV);
  }

  const vecA = sdk.vector('vec.a', { x: ballX + 60, y: ballY }, {
    value: -g,
    direction: 'up',
    scale: 4,
    label: 'a'
  });
  objects.push(...vecA);

  const callout = sdk.callout(ballX + 110, ballY - 20, [motionStateStr, gravityStateStr], {
    id: 'callout.toss'
  });
  objects.push(...callout);

  const readouts = [
    { id: 'motionState', value: motionStateStr },
    { id: 'gravityState', value: gravityStateStr }
  ];

  const quantities = {
    launchSpeed: v0,
    gravity: g,
    apexTime: tTop,
    apexHeight: hMax,
    velocity: v,
    height: h
  };

  return { frame: sdk.frame(objects, { width: 640, height: 420, readouts }), quantities };
}
